import React, { useEffect, useState } from "react";
import { createRoot } from "react-dom/client";
import { ArrowLeft, ArrowRight, Check, ChevronDown, CircleHelp, CirclePlay, Clapperboard, CloudUpload, Download, FileAudio, Film, FolderOpen, Gauge, History, ImagePlus, Languages, LayoutDashboard, Library, LogOut, Menu, Mic2, Moon, MoreHorizontal, Pause, Pencil, Play, Plus, RefreshCw, RotateCcw, Settings, ShieldCheck, Sparkles, Sun, Trash2, Upload, Volume2, WandSparkles, X } from "lucide-react";
